const STORE='READwy_new_2026_local_';let page='startup',user=null,selectedGrade=7,assessmentAnswers={},activeModule='',oralStarted=0,oralEnd=0,oralMisses=0,scoreInput={},navigationBusy=false,authRole='',authPending=null,authDemoCode='';
const demoAccounts=new Map([['student.demo@readwy.test',{name:'Demo Student',role:'student',grade:7,password:'ReadwyStudent1!',verified:true}],['teacher.demo@readwy.test',{name:'Demo Teacher',role:'teacher',grade:7,password:'ReadwyTeacher1!',verified:true}]]);
