function h(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(k,val){try{localStorage.setItem(STORE+k,JSON.stringify(val))}catch(e){showPageStatus('Browser storage is unavailable. This session may not be saved.')}}
function load(k,fallback){try{return JSON.parse(localStorage.getItem(STORE+k))||fallback}catch(e){return fallback}}
function safeURL(p){return encodeURI(p).replace(/#/g,'%23')}
