function selectDemoRole(role){if(!['student','teacher'].includes(role))return;authRole=role;document.querySelectorAll('.login-role').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.role===role)));const email=document.getElementById('loginEmail'),password=document.getElementById('loginPassword'),remember=document.getElementById('rememberDemo'),eye=document.querySelector('.login-visibility'),submit=document.querySelector('.login-submit');[email,password,remember,eye,submit].forEach(control=>{if(control)control.disabled=false});const account=demoAccounts.get(`${role}.demo@readwy.test`);if(email&&account){email.value=account.email||`${role}.demo@readwy.test`;password.value=account.password}try{const remembered=localStorage.getItem(STORE+'rememberedEmail'),rememberedAccount=demoAccounts.get(remembered);if(remembered&&rememberedAccount?.role===role){email.value=remembered;remember.checked=true}}catch(e){}}
function setLoginStatus(message){const status=document.querySelector('.login-status');if(status)status.textContent=message}
function initializeDemoLogin(){authRole='';document.querySelectorAll('.login-role').forEach(button=>button.setAttribute('aria-pressed','false'));['loginEmail','loginPassword','rememberDemo'].forEach(id=>{const control=document.getElementById(id);if(control){control.disabled=true;if(control.type==='checkbox')control.checked=false;else control.value=''}});['.login-visibility','.login-submit','.login-google'].forEach(selector=>{const control=document.querySelector(selector);if(control)control.disabled=true});setLoginStatus('')}
function rememberDemoEmail(checkbox){try{if(checkbox.checked)localStorage.setItem(STORE+'rememberedEmail',document.getElementById('loginEmail').value.trim());else localStorage.removeItem(STORE+'rememberedEmail')}catch(e){setLoginStatus('Remember me is unavailable in this browser.')}}
function toggleDemoPassword(){const field=document.getElementById('loginPassword');if(field)field.type=field.type==='password'?'text':'password'}
function showAuthModal(content){const root=document.getElementById('authModalRoot');if(root)root.innerHTML=`<div class="auth-modal-layer" onclick="if(event.target===this)closeAuthModal()"><section class="auth-modal" role="dialog" aria-modal="true">${content}</section></div>`}
function closeAuthModal(){const root=document.getElementById('authModalRoot');if(root)root.innerHTML=''}
function modalStatus(message){const status=document.querySelector('.auth-modal-status');if(status)status.textContent=message}
function completeDemoLogin(account,email){user={name:account.name,email,role:account.role,grade:account.grade||7};selectedGrade=Number(user.grade);save('user',user);closeAuthModal();go('subject')}
function demoLogin(event){event.preventDefault();if(!authRole)return setLoginStatus('Choose Student or Teacher first.');const email=document.getElementById('loginEmail').value.trim().toLowerCase(),password=document.getElementById('loginPassword').value,account=demoAccounts.get(email);if(!email||!password)return setLoginStatus('Enter both your email and password.');if(!account){setLoginStatus('No demo account found. Choose Sign Up or select a demo role.');return}if(account.role!==authRole){setLoginStatus('Choose the role registered for this account.');return}if(account.password!==password){setLoginStatus('That demo password does not match.');return}if(!account.verified){setLoginStatus('Verify this demo email before signing in.');return}completeDemoLogin(account,email)}
function openDemoSignup(){authRole='';go('signup')}
function requestDemoReset(){if(!authRole){setLoginStatus('Choose Student or Teacher first.');return}const email=document.getElementById('loginEmail').value.trim().toLowerCase(),account=demoAccounts.get(email);if(!account){setLoginStatus('Enter a registered demo email first.');document.getElementById('loginEmail').focus();return}authPending={kind:'reset',email};authDemoCode=String(Math.floor(100000+Math.random()*900000));showAuthModal(`<h2>Demo Password Reset</h2><p>No email was sent to ${h(email)}. Enter the displayed demo code and choose a new password.</p><div class="auth-demo-code">${authDemoCode}</div><form onsubmit="verifyDemoReset(event)"><label for="resetCode">Verification code</label><input id="resetCode" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code"><label for="resetPassword">New password (8+ characters)</label><input id="resetPassword" type="password" minlength="8" required autocomplete="new-password"><div class="row"><button class="btn" type="submit">Verify and reset</button><button class="btn secondary" type="button" onclick="closeAuthModal()">Cancel</button></div><p class="auth-modal-status" role="status"></p></form>`)}
function verifyDemoReset(event){event.preventDefault();if(document.getElementById('resetCode').value!==authDemoCode){modalStatus('The code does not match.');return}const account=demoAccounts.get(authPending.email);account.password=document.getElementById('resetPassword').value;document.getElementById('loginEmail').value=authPending.email;document.getElementById('loginPassword').value=account.password;authPending=null;authDemoCode='';closeAuthModal();setLoginStatus('Demo password updated for this tab session.')}
function startOwlFlight(){stopOwlFlight()}
function syncOwlMotion(){if(document.hidden){document.documentElement.classList.add('page-hidden');document.querySelectorAll('.startup-environment svg').forEach(svg=>svg.pauseAnimations());stopOwlFlight();return}document.documentElement.classList.remove('page-hidden');document.querySelectorAll('.startup-environment svg').forEach(svg=>svg.unpauseAnimations());stopOwlFlight()}
document.addEventListener('visibilitychange',syncOwlMotion);
if(owlMotionPreference.addEventListener)owlMotionPreference.addEventListener('change',syncOwlMotion);else owlMotionPreference.addListener(syncOwlMotion);
function render(){setOwl(page);if(page==='orst-welcome')renderORSTWelcome();else if(page==='settings')renderSettings();else if(page==='profile')renderProfile();else renderWork();renderToolbar()}
function workLayout(title,inside){page='work';app.innerHTML=`<section id="work"><header class="workhead"><div class="brand">✦ READwy <small style="font-size:12px">Academy of Reading</small></div><div class="row"><span>${h(user?.name||'Local Visitor')} · Grade ${selectedGrade}</span><button class="btn secondary compact back-action" onclick="go('map')">← Map</button><button class="btn secondary compact" onclick="showDashboard()">Dashboard</button></div></header><article class="workarea"><h1>${h(title)}</h1>${inside}</article></section>`;setOwl('work');nav.innerHTML='<button class="btn secondary compact" onclick="go(\'map\')">☷ Map</button><button class="btn secondary compact" onclick="showDashboard()">Dashboard</button>';renderToolbar();scrollAppToTop()}
function openModule(mod){if(['srst','wst'].includes(mod))return openWST();if(mod==='aral'&&typeof aralView!=='undefined'){aralView.panel=1;aralView.week=1;aralView.answers=[];aralView.message='';aralLessonView.active=false}if(mod==='orst')return startORSTSpell();if(navigationBusy)return;activeModule=mod;return transition('work',()=>modulePage(mod))}
function renderWork(){modulePage(activeModule||'dashboard')}
function showDashboard(){if(navigationBusy)return;activeModule='dashboard';return transition('work',()=>modulePage('dashboard'))}
const PROGRAMS=[['gst','Reading Check-In','Grade-specific screening passages and questions'],['srst','Silent Reading Screening Test','Same source: Reading Check-In, 40 items per grade'],['orst','Voice Station','Graded passages, reading timing, miscues and comprehension'],['aral','Catch-Up Express','Eight-week reading and writing catch-up journey'],['interv','Intervention','Skill-focused instructional tasks'],['sra','READwy Reading Lab','Color-banded source passages'],['reports','Reading Reports','Saved attempts, export and original templates']];
function modulePage(mod){activeModule=mod;if(mod==='dashboard')return workLayout('Academy Learning Dashboard',`<p class="muted">Choose your next stop on the Reading Express.</p><div class="cards">${PROGRAMS.map(([key,title,desc])=>`<section class="card"><h3>${h(title)}</h3><p>${h(desc)}</p><button class="btn" onclick="openModule('${key}')">Open</button></section>`).join('')}</div>`);
if(['gst','srst'].includes(mod))return renderGST(mod);
if(mod==='orst')return renderORST();if(mod==='sra')return renderSRA();if(mod==='interv')return renderInter();if(mod==='aral')return renderAral();if(mod==='reports')return renderReports();}
function gradeSelector(mod){return `<div class="row"><label for="gradeSel">Grade:</label><select class="forminput gradepick" id="gradeSel" onchange="selectedGrade=Number(this.value);modulePage('${mod}')">${[7,8,9,10].map(g=>`<option ${selectedGrade===g?'selected':''} value="${g}">Grade ${g}</option>`).join('')}</select><button class="btn secondary compact" onclick="showDashboard()">Dashboard</button></div>`}
function parasHTML(paras){return paras.map((p,i)=>{let s=h(p);if(/^Grade \d+|^English \d+|^Learner.s Copy$|^Questions$|^Reading Profile$|^READwy Reading Lab Chart$/.test(p))return `<h3>${s}</h3>`;return `<p>${s}</p>`}).join('')}
function renderGST(mod){if(mod==='gst')return openGSTBook();const source=SOURCE_DATA.gst[String(selectedGrade)]||[];const saved=load('answer_'+selectedGrade,{});let qs=source.filter(s=>/^\s*(?:[1-9]|[1-3][0-9]|40)[.)]\s+/.test(s));
workLayout(mod==='gst'?'Reading Check-In':'Silent Reading Screening Test',`${gradeSelector(mod)}<p class="notice">This is the complete original source section for Grade ${selectedGrade}. The user identified the Reading Check-In as the shared source for the 40-item SRST. The original questions and passages are preserved verbatim below. A verified answer key was not supplied, so this screen records responses but does not invent or auto-grade correct answers.</p><div class="row"><button class="btn" onclick="saveReading('${mod}')">Save Reading Session</button><button class="btn secondary" onclick="window.print()">Print Assessment</button></div><p class="muted small">Numbered items detected in plain text: ${qs.length}. Some items are embedded with irregular formatting or illustrations; consult the downloadable original to check the exact layout.</p><div class="reading scrollbox" id="fullReading">${parasHTML(source)}</div><div class="panel"><h2>Student Answer Sheet — 40 Items</h2><p>Save each selected letter for teacher review. Correct scores require an authenticated answer key.</p><div class="grid">${Array.from({length:40},(_,i)=>`<label>${i+1}. <select class="forminput" id="q${i+1}" onchange="storeAnswer(${i+1},this.value)"><option value="">— Select —</option>${['A','B','C','D'].map(c=>`<option value="${c}" ${saved[i+1]===c?'selected':''}>${c}</option>`).join('')}</select></label>`).join('')}</div><p><button class="btn" onclick="saveReading('${mod}')">Save 40-item Answer Sheet</button></p></div>`)}
function storeAnswer(i,v){let a=load('answer_'+selectedGrade,{});a[i]=v;save('answer_'+selectedGrade,a)}
function saveReading(mod){let a=load('answer_'+selectedGrade,{});let filled=Object.values(a).filter(Boolean).length;save('assessment_'+selectedGrade,{type:mod,answered:filled,date:new Date().toISOString(),answers:a});showPageStatus(`${filled} of 40 responses saved on this browser. No score calculated without the correct answer key.`)}
let renderORST;
function renderSRAReading(){const raw=SOURCE_DATA.sra, groups={};let last='Unsorted';for(let line of raw){if(/BAND\s*[—–-]|^READwy Reading Lab Chart/i.test(line))last=line.slice(0,80);(groups[last]??=[]).push(line)}let keys=Object.keys(groups);workLayout('READwy Reading Lab',`<p class="notice">All source passages are included as supplied, organized by their original color-band headings. The provided passages do not include a verified answer key; answers must be checked against teacher references.</p><div class="row"><label>Color/section <select class="forminput" id="sraColor" onchange="sraShow(this.value)">${keys.map((x,i)=>`<option value="${i}">${h(x)}</option>`).join('')}</select></label></div><div class="reading scrollbox" id="sraReading">${parasHTML(groups[keys[0]]||[])}</div>`);window._sraGroups=keys.map(k=>groups[k])}
function sraShow(n){document.getElementById('sraReading').innerHTML=parasHTML(window._sraGroups[Number(n)]||[])}
function renderInterActivities(){let raw=SOURCE_DATA.inter;workLayout('Reading Intervention',`<div class="notice">Use the original intervention task list for the appropriate skill and grade. The complete original Word file remains available.</div><div class="reading">${parasHTML(raw)}</div><a href="${safeURL(RES+'Learning Programs/Intervention Task List.docx')}" download>Download Intervention Task List</a><h2>Session notes</h2><textarea id="interNotes" class="forminput" rows="5" placeholder="Record target skill, practice, feedback and next steps">${h(load('interNotes_'+selectedGrade,''))}</textarea><p><button class="btn" onclick="save('interNotes_'+selectedGrade,document.getElementById('interNotes').value);showPageStatus('Saved on this browser')">Save Session Notes</button></p>`)}
function renderAral(){let p=SOURCE_DATA.pdfs;workLayout('Catch-Up Express',`<p class="notice">Activities adapted from DepEd ARAL-Reading Plus Key Stage 3 learning materials (Department of Education). Passages and pictures marked READwy are original.</p><h2>Weekly Progress</h2><div class="panel"><label>Week <select class="forminput gradepick" id="aralWeek">${Array.from({length:8},(_,i)=>`<option>${i+1}</option>`).join('')}</select></label><label>Mastery result <select class="forminput gradepick" id="aralStatus"><option>Needs Work</option><option>Mastered</option><option>Not Yet Assessed</option></select></label><p><button class="btn" onclick="aralSave()">Save Weekly Progress</button></p><div id="aralLog"></div></div>`);aralLog()}
function aralSave(){let a=load('aral_'+selectedGrade,{});a[document.getElementById('aralWeek').value]={status:document.getElementById('aralStatus').value,date:new Date().toISOString()};save('aral_'+selectedGrade,a);aralLog()}
function aralLog(){let el=document.getElementById('aralLog');if(el)el.innerHTML=Object.entries(load('aral_'+selectedGrade,{})).map(([w,a])=>`<p>Week ${h(w)}: ${h(a.status)} — ${new Date(a.date).toLocaleDateString()}</p>`).join('')}
/* Post-Test Express: a train-themed Phil-IRI post-test shown full-screen in an isolated document. */
function postExpressRender(){window.renderReportsClassic=renderReportsClassic;
 if(window.__reportsClassic){window.__reportsClassic=false;return renderReportsClassic()}
 page='work';activeModule='reports';nav.innerHTML='';stopOwlFlight();owl.dataset.motion='still';owl.style.display='none';
 if(!document.getElementById('post-express-style')){const st=document.createElement('style');st.id='post-express-style';st.textContent='.post-express-screen{position:relative;width:100%;height:100%;overflow:hidden;background:#0b1410}.post-express-frame{display:block;width:100%;height:100%;border:0;background:#0b1410}body:has(.post-express-screen) .fixednav,body:has(.post-express-screen) #nav{display:none!important}body:has(.post-express-screen) #app{padding:0!important;inset:0!important;height:100%!important}';document.head.appendChild(st)}
 if(app.querySelector('.post-express-frame'))return;
 app.innerHTML='<section class="post-express-screen" aria-label="Post-Test Express"><iframe class="post-express-frame" title="Post-Test Express" allow="fullscreen" allowfullscreen></iframe></section>';
 const f=app.querySelector('.post-express-frame');let tries=0;
 const put=()=>{if(!f.isConnected)return;const doc=document.getElementById('post-express-document');if(doc){f.srcdoc=JSON.parse(doc.textContent);return}if(++tries<200)setTimeout(put,50)};put();
 f.addEventListener('load',()=>f.contentDocument?.getElementById('stage')?.focus({preventScroll:true}),{once:true})}
function renderReports(){return postExpressRender();}function renderReportsClassic(){let a=load('assessment_'+selectedGrade,{}),oral=load('oral_'+selectedGrade,{});workLayout('Teacher & Learner Reports',`${gradeSelector('reports')}<p class="notice">Records in this demonstration are saved only in the current browser, not synchronized across students or devices. This is not a secure teacher database and must not be used as an official consolidated school record without a backend.</p><div class="cards"><div class="card"><h3>Screening Responses</h3><p>Answered: ${a.answered??0} of 40</p><p>Score: Not available until a verified answer key is supplied</p></div><div class="card"><h3>Oral Reading Profile</h3><p>Accuracy: ${oral.accuracy==null?'No result':oral.accuracy.toFixed(2)+'%'}</p><p>Comprehension: ${oral.comprehension==null?'No result':oral.comprehension.toFixed(2)+'%'}</p></div></div><div class="row" style="margin-top:15px"><button class="btn" onclick="exportCSV()">Export local responses as CSV</button><button class="btn secondary" onclick="window.print()">Print Report</button></div><h2>Original School Report Template</h2><a href="${safeURL(RES+'Teacher Reports/EAPIHS_PhilIRI_Form_1B_Reading_Report.xlsx')}" download>Download EAPIHS PHIL-IRI Form 1B (Excel)</a><p class="muted">The supplied Excel remains an original template; it is not automatically populated in this browser-only build.</p>`)}
function exportCSV(){let a=load('answer_'+selectedGrade,{}),oral=load('oral_'+selectedGrade,{});let rows=[['Grade','Item','Answer'],...Array.from({length:40},(_,i)=>[selectedGrade,i+1,a[i+1]||''])];rows.push(['Word-reading accuracy','',oral.accuracy??''],['Comprehension','',oral.comprehension??'']);let csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const b=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),u=URL.createObjectURL(b),link=document.createElement('a');link.href=u;link.download=`READwy_Grade${selectedGrade}_Local_Responses.csv`;link.click();URL.revokeObjectURL(u)}

let renderSignup;
function toggleSignupPassword(button){const input=document.getElementById('signupPassword');if(!input)return;input.type=input.type==='password'?'text':'password';button.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')}
function submitSignupForm(event,role){event.preventDefault();const form=event.currentTarget,status=form.querySelector('.signup-form-status');if(role==='student'&&!/^\d{12}$/.test(form.elements.signupLrn.value)){status.textContent='LRN must contain exactly 12 digits.';form.elements.signupLrn.focus();return}if(!form.checkValidity()){status.textContent='Please complete the required fields and correct any invalid information.';form.reportValidity();return}status.textContent='Your details are ready, but account creation is unavailable until secure authentication, database, and verification services are configured. No account was created.'}

function renderToolbar(){nav.className='fixednav journey-toolbar';nav.setAttribute('role','navigation');nav.setAttribute('aria-label','Main navigation');const visible=['work','settings','profile'].includes(page)&&!(page==='work'&&['gst','orst','aral','sra'].includes(activeModule));nav.innerHTML=visible?[['Home','⌂',"showDashboard()",page==='work'&&activeModule==='dashboard'],['Journey','♧',"go('map')",page==='map'],['Settings','⚙',"go('settings')",page==='settings'],['Profile','♙',"go('profile')",page==='profile']].map(([label,icon,action,current])=>`<button type="button" onclick="${action}" ${current?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</button>`).join(''):''}
function applyPreferences(){const settings=load('preferences',{});document.documentElement.classList.toggle('reduced-motion',!!settings.reduceMotion);document.documentElement.style.setProperty('--reading-size',(settings.readingSize||19)+'px')}
function renderSettings(){const settings=load('preferences',{});workLayout('Settings',`<form class="settings-form card" onsubmit="savePreferences(event)"><label><input name="reduceMotion" type="checkbox" ${settings.reduceMotion?'checked':''}> Reduce animations</label><label for="readingSize">Reading text size</label><select class="forminput" id="readingSize" name="readingSize">${[[17,'Small'],[19,'Standard'],[23,'Large'],[27,'Extra large']].map(([n,label])=>`<option value="${n}" ${(settings.readingSize||19)===n?'selected':''}>${label}</option>`).join('')}</select><button class="btn" type="submit">Save Settings</button><p role="status" id="settingsStatus"></p></form>`);page='settings';renderToolbar()}
function savePreferences(event){event.preventDefault();const form=event.currentTarget;save('preferences',{reduceMotion:form.elements.reduceMotion.checked,readingSize:Number(form.elements.readingSize.value)});applyPreferences();document.getElementById('settingsStatus').textContent='Settings saved on this browser.'}
function renderProfile(){workLayout('Profile',`<form class="settings-form card" onsubmit="saveProfile(event)"><p>${h(user?.role||'Local visitor')}${user?.email?' · '+h(user.email):''}</p><label for="profileName">Name</label><input class="forminput" id="profileName" name="name" value="${h(user?.name||'Local Visitor')}" required maxlength="100"><label for="profileGrade">Grade level</label><select class="forminput" id="profileGrade" name="grade">${[7,8,9,10].map(g=>`<option value="${g}" ${g===selectedGrade?'selected':''}>Grade ${g}</option>`).join('')}</select><button class="btn" type="submit">Save Profile</button><p role="status" id="profileStatus"></p></form>`);page='profile';renderToolbar()}
function saveProfile(event){event.preventDefault();const form=event.currentTarget,name=form.elements.name.value.trim();if(!name){form.elements.name.setCustomValidity('Enter your name.');form.elements.name.reportValidity();form.elements.name.oninput=()=>form.elements.name.setCustomValidity('');return}selectedGrade=Number(form.elements.grade.value);user={...(user||{role:'visitor'}),name,grade:selectedGrade};save('user',user);renderProfile();document.getElementById('profileStatus').textContent='Profile saved on this browser.'}
applyPreferences();


function landscapeWidth(){return document.getElementById('landscape-shell')?.clientWidth||Math.max(window.innerWidth,window.innerHeight)}
function landscapeHeight(){return document.getElementById('landscape-shell')?.clientHeight||Math.min(window.innerWidth,window.innerHeight)}
function scrollAppToTop(){app.scrollTo(0,0)}
function refreshLandscapeLayout(){if(owl.dataset.motion==='flight')startOwlFlight()}
window.addEventListener('resize',refreshLandscapeLayout,{passive:true});
window.screen?.orientation?.addEventListener('change',()=>{refreshLandscapeLayout()});
document.addEventListener('fullscreenchange',()=>{refreshLandscapeLayout()});



let welcomeWanderAnimation=null,welcomeWanderTimer=0;
function stopWelcomeWandering(){clearTimeout(welcomeWanderTimer);welcomeWanderTimer=0;if(welcomeWanderAnimation)welcomeWanderAnimation.cancel();welcomeWanderAnimation=null;owl.style.animation='';owl.style.zIndex=''}
function startWelcomeWandering(){stopOwlFlight()}

document.addEventListener('visibilitychange',()=>{stopWelcomeWandering();if(!document.hidden&&['login','signup','subject','journey','map'].includes(page))startWelcomeWandering()});


function showPageStatus(message){
 const host=document.querySelector('.workarea,.login-controls,.signup-flow-content,.subject-screen')||app;
 let status=host.querySelector('.page-status');
 if(!status){status=document.createElement('p');status.className='page-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');host.append(status)}
 status.textContent=message;
}


